// Original pixel artwork for the Bellhaven cutscene. Front-facing poses only.
const GLP_ARC_IDS = ['glp_monday','glp_vivi','glp_nine','glp_igaram','glp_five','glp_valentine'];
const glpCastSheet = new Image();
glpCastSheet.src = 'data:image/webp;base64,';
for (const [i, name] of ['Miss Monday','Vivi','Mr. 9','Igaram','Mr. 5','Miss Valentine'].entries()) {
  const id = GLP_ARC_IDS[i];
  NPCS[id] = {
    n:name, look:LK({}), lines:[''],
    atlas:()=>getAtlas('glp:arc:'+id,()=>dawnPixelAtlas(64,76,{idle:0},1,
      g=>g.drawImage(glpCastSheet,i*128,0,128,152,0,0,128,152)))
  };
}
